```yaml
name: Claude Code Review
on:
  issue_comment:
    types: [created]
  issues:
    types: [opened]

jobs:
  claude-code-review:
    runs-on: ubuntu-latest
    if: |
      github.event_name == 'issues' || 
      (github.event_name == 'issue_comment' && 
       (contains(github.event.comment.body, '@claude') || 
        contains(github.event.issue.title, '@claude')))
    steps:
      - name: Check if user is collaborator
        id: check_collaborator
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { data: issue } = await github.rest.issues.get({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number
            });

            const { data: collaboration } = await github.rest.repos.getCollaboratorPermissionLevel({
              owner: context.repo.owner,
              repo: context.repo.repo,
              username: context.actor
            });

            if (['admin', 'maintain', 'write', 'triage'].includes(collaboration.permission)) {
              console.log('User is a collaborator');
              return true;
            } else {
              console.log('User is not a collaborator');
              return false;
            }

      - name: Run Claude Code Action
        if: steps.check_collaborator.outputs.result == 'true'
        uses: anthropics/claude-code-action@v1
        with:
          anthropic_api_key: ${{ secrets.ANTHROPIC_API_KEY }}
          claude_code_oauth_token: ${{ secrets.CLAUDE_CODE_OAUTH_TOKEN }}
          allowed_non_write_users: ""
          include_comments_by_actor: "false"
